<template><form @submit.prevent="submit" class="eng-divider"><h3>Tạo voucher cho chiến dịch</h3><div class="eng-grid"><div><label for="campaign-code">Mã voucher</label><input id="campaign-code" v-model="form.ma_code" maxlength="50" pattern="[A-Za-z0-9_-]+" required></div><div><label for="campaign-voucher-name">Tên voucher</label><input id="campaign-voucher-name" v-model="form.ten_giam_gia" maxlength="255" required></div></div><label for="campaign-voucher-description">Mô tả</label><textarea id="campaign-voucher-description" v-model="form.mo_ta" maxlength="2000"></textarea><div class="eng-grid"><div><label for="campaign-discount-type">Loại giảm</label><select id="campaign-discount-type" v-model="form.loai_giam"><option value="phan_tram">Phần trăm</option><option value="co_dinh">Số tiền cố định</option></select></div><div><label for="campaign-discount">Giá trị giảm</label><input id="campaign-discount" type="number" v-model.number="form.gia_tri" min="0" :max="form.loai_giam==='phan_tram'?100:9999999999999" step="0.01" required></div><div><label for="campaign-max-discount">Giảm tối đa · tùy chọn</label><input id="campaign-max-discount" type="number" min="0" v-model="form.giam_toi_da"></div><div><label for="campaign-min-order">Đơn hàng tối thiểu</label><input id="campaign-min-order" type="number" min="0" v-model.number="form.gia_tri_toi_thieu"></div><div><label for="campaign-total-uses">Lượt sử dụng tổng</label><input id="campaign-total-uses" type="number" min="1" v-model.number="form.so_luong" required></div><div><label for="campaign-customer-uses">Giới hạn mỗi Customer</label><input id="campaign-customer-uses" type="number" min="1" v-model.number="form.gioi_han_moi_khach" required></div><div><label for="campaign-start-date">Ngày bắt đầu · giờ Việt Nam</label><input id="campaign-start-date" type="date" v-model="form.ngay_bat_dau"></div><div><label for="campaign-end-date">Ngày hết hạn · giờ Việt Nam</label><input id="campaign-end-date" type="date" v-model="form.ngay_ket_thuc" :min="form.ngay_bat_dau"></div></div><p v-if="error" class="eng-error">{{ error }}</p><div class="eng-actions"><button class="eng-btn secondary" :disabled="loading">{{ loading?'Đang tạo…':'Tạo voucher' }}</button></div></form></template>
<script>
import { engagementApi, engagementError } from '../../services/engagement';
export default {emits:['created'],data:()=>({form:{ma_code:'',ten_giam_gia:'',mo_ta:'',loai_giam:'phan_tram',gia_tri:10,giam_toi_da:'',gia_tri_toi_thieu:0,so_luong:100,gioi_han_moi_khach:1,doi_tuong:'all',ngay_bat_dau:'',ngay_ket_thuc:'',trang_thai:1},loading:false,error:''}),methods:{async submit(){if(this.loading)return;this.loading=true;this.error='';try{await engagementApi('admin/ma-giam-gia/create',{method:'post',data:{...this.form,giam_toi_da:this.form.giam_toi_da===''?null:Number(this.form.giam_toi_da)}});this.$emit('created',this.form.ma_code.trim().toUpperCase());this.form.ma_code='';this.form.ten_giam_gia='';}catch(e){this.error=engagementError(e);}finally{this.loading=false;}}}};
</script>
